# -*- coding: utf-8 -*-
# Одноразовый скрипт интеграции: вставить 4 строки новых модулей в таблицу CLAUDE.md
# после строки с `clone.py`.
import io

ROWS = [
    r'| `save_io.py` | ~430 | **Система сохранений.** Полный сейв забега — JSON в `saves/save_<N>.json` (папка рядом с игрой; в сборке — рядом с EXE, `core.BASE`). `save(g, label=None)` — снапшот: круг/комната/позиция/герой + `heroes` (снапшот КАЖДОГО героя забега, см. `swap.py`) + `came_from` + состояние каждой посещённой карты (`maps`: `visited/cleared/spawned/locked/boss_spawned`, мобы `[[kind,x,y,scale,hp,dir]]` — только живые не-манекены, scale считается из maxhp; дропы `[["W",x,y,wid]|["R",x,y,rid]]`, ящики `ct`, механизмы `mc`). `restore(g, save_id)`: `apply_character` + `clear_cache` → `Campaign` + `came_from` → карты через `_restore_map` (при `containers.ROLL_SPAWN=False`: какие ящики появились, решает сейв; `locked` ставится только при живых мобах) → `g.Player()` → `g.go(room,None)` → позиция из сейва → `restore_player` → `g.heroes`; транзиент (fx/projs/клоны/гарпуны/бой) не сохраняется. `snapshot_player(pl)` — постоянный прогресс героя (hp/mana/уровень/навыки/`skill_cooldowns` (только активные)/slots/bag/equip/resources/last_weapon/goggles/hold_pool/hold_rest/bd_note/amps/xb_ammo/xb_cd); `restore_player` — порядок: навыки/экипировка → `on_equipment_changed` (пересчёт максимумов) → hp/мана зажаты. `list_saves()` — меты сейвов, новые первыми. В сети (`g.net`) `save`/`restore` бросают `RuntimeError`. |',
    r'| `saves_menu.py` | ~330 | Вкладка «СОХРАНЕНИЯ» главного меню и меню «ЗАГРУЗИТЬ» из паузы. `MODES=("saves","saves_char")`; `open_saves(g, back)` — запоминает, куда вернёт Esc (`_BACK`: "start"/"pause"); список сейвов из `save_io.list_saves()` (ленивый импорт), Enter — экран героев сейва (с уровнем и меткой «последний игравший»), выбор героя — `save_io.restore`. Роутинг: `menu_key`/`menu_event`/`draw_menu` при `g.menu_mode in MODES`; в сети открываться отказывается. |',
    r'| `pause_menu.py` | ~190 | Меню паузы (Esc): пять кнопок — ПРОДОЛЖИТЬ, ВЫБОР ПЕРСОНАЖА, СОХРАНИТЬСЯ, ЗАГРУЗИТЬ, ГЛАВНОЕ МЕНЮ (`OPTIONS`; действия доставляет `Game.menu_action`). Клавиши 1..5/KP1..KP5, Esc — вернуться в забег. Координаты — `SETTINGS["menu_layout_pause"]` (`layout(g)`: setdefault+clamp, старый формат 3 кнопок мигрирует на 5 автоматически), редактор F3: drag/колесо/+/- (`_resize`). В сети кнопки swap/save/load приглушены (`NET_LOCKED`, подсказка через `fx.text`). Роутинг: `key`/`event`/`draw` при `g.menu_mode == "pause"`. |',
    r'| `swap.py` | ~270 | **Смена героя посреди забега** (экран «ВЫБОР ПЕРСОНАЖА» из паузы). Забег хранит `g.heroes = {char_id: снапшот}` (формат — `save_io.snapshot_player`); `init(g)` из `new_game` (только loop==0), `register(g)` — обновить снапшот текущего героя (вызывается и при новом круге). `switch(g, cid)` — порядок критичен: снапшот СТАРОГО ДО `apply_character` → отмена крафта (ресурсы падают) → `apply_character`+`clear_cache`+`SETTINGS["last_character"]` → новый `g.Player()` → `restore_player` (его личное состояние) → сброс транзиента (`_reset_transient`: atk/channel/hold/grab/clones) → `_place` на место старого (центр/ноги; стены — `floor_below`, соседние клетки, крайний случай — `Game.place`) → `register` нового. `switch_open`/`menu_key` (стрелки/W-S/цифры/Enter, Esc — назад в паузу)/`menu_event` (клик по карточке)/`draw_menu` (карточки с превью и полосками HP/маны из живых значений или снапшота). В сети отказывается с подсказкой. |',
]

p = 'CLAUDE.md'
lines = io.open(p, encoding='utf-8').read().split('\n')
idx = next(i for i, l in enumerate(lines) if l.startswith('| `clone.py`'))
lines[idx + 1:idx + 1] = ROWS
io.open(p, 'w', encoding='utf-8', newline='\n').write('\n'.join(lines))
print('inserted 4 rows after line', idx + 1, '->', lines[idx][:20].strip())
